import React from "react";
import {BrowserRouter,Routes,Route} from 'react-router-dom';
import './App.css';
import ChatBot from './components/Chatbot';

function App() {
  return (
    <Routes>
      <Route path="/chatbot" element={<ChatBot/>}></Route>
    </Routes>
  );
}

export default App;
